{
"sql": "SELECT g.Name, SUM(il.UnitPrice * il.Quantity) AS TotalSales FROM Genre g JOIN Track t ON g.GenreId = t.GenreId JOIN InvoiceLine il ON t.TrackId = il.TrackId GROUP BY g.GenreId ORDER BY TotalSales DESC LIMIT 5"
}

{
"sql": "SELECT MediaType.Name, COUNT(Track.TrackId) AS TrackCount FROM Track JOIN MediaType ON Track.MediaTypeId = MediaType.MediaTypeId GROUP BY MediaType.MediaTypeId ORDER BY TrackCount DESC LIMIT 1"
}

{
"sql": "SELECT e.FirstName, e.LastName, COUNT(c.CustomerId) AS customer_count FROM Employee e JOIN Customer c ON e.EmployeeId = c.SupportRepId GROUP BY e.EmployeeId ORDER BY customer_count DESC LIMIT 1"
}

{
"sql": "SELECT p.Name, COUNT(pt.TrackId) AS TrackCount FROM Playlist p LEFT JOIN PlaylistTrack pt ON p.PlaylistId = pt.PlaylistId GROUP BY p.PlaylistId, p.Name ORDER BY TrackCount DESC;"
}

{
"sql": "SELECT SUM(Total) AS total_revenue_2021 FROM Invoice WHERE strftime('%Y', InvoiceDate) = '2021';"
}

{
"sql": "SELECT BillingCountry, AVG(Total) AS AvgTotal FROM Invoice GROUP BY BillingCountry ORDER BY AvgTotal DESC"
}

{
"sql": "SELECT c.FirstName || ' ' || c.LastName AS CustomerName, SUM(i.Total) AS TotalSpending, RANK() OVER (ORDER BY SUM(i.Total) DESC) AS Rank FROM Customer c JOIN Invoice i ON c.CustomerId = i.CustomerId GROUP BY c.CustomerId ORDER BY TotalSpending DESC LIMIT 5"
}

{
"sql": "SELECT a.Name, COUNT(DISTINCT t.GenreId) AS distinct_genres FROM Artist a JOIN Album al ON a.ArtistId = al.ArtistId JOIN Track t ON al.AlbumId = t.AlbumId GROUP BY a.ArtistId HAVING COUNT(DISTINCT t.GenreId) > 3 ORDER BY distinct_genres DESC;"
}
